            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"140\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"200\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">THE GREENSPAN IRONY</text><text x=\"550\" y=\"250\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">What did he write, and what did he do?</text><text x=\"550\" y=\"295\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Compare 1966 with 1987 to 2006</text><rect x=\"120\" y=\"430\" width=\"400\" height=\"140\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"320\" y=\"510\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"24\">Wrote: gold</text><rect x=\"580\" y=\"430\" width=\"400\" height=\"140\" rx=\"20\" fill=\"rgba(59,130,246,0.15)\" stroke=\"#3b82f6\" stroke-width=\"2\"/><text x=\"780\" y=\"510\" text-anchor=\"middle\" fill=\"#3b82f6\" font-size=\"24\">Did: paper money</text></svg>",
