            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THE ECONOMISTS' VERDICT</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">A rough map, not a vote</text><rect x=\"80\" y=\"170\" width=\"940\" height=\"200\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"550\" y=\"225\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">MOSTLY ACCEPTED</text><text x=\"550\" y=\"280\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Prices beat planning; controls cause shortages</text><text x=\"550\" y=\"325\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Inflation is monetary; rent-seeking is real</text><rect x=\"80\" y=\"410\" width=\"940\" height=\"170\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"550\" y=\"465\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"24\">CONTESTED</text><text x=\"550\" y=\"520\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Antitrust; judging the robber-baron era</text><rect x=\"80\" y=\"620\" width=\"940\" height=\"200\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"550\" y=\"675\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"24\">MOSTLY REJECTED</text><text x=\"550\" y=\"730\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Gold standard; market failures negligible</text><text x=\"550\" y=\"775\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">No taxes, no public schools</text><text x=\"550\" y=\"900\" text-anchor=\"middle\" fill=\"#888\" font-size=\"19\">The moral thesis is outside economics entirely</text></svg>",
